		     /*saveMasterWmReReturnEntryForBuyerPop*/
                   INSERT INTO BNTWMRE
                   (
                     WMRE_NO
                   , BUYER
                   , PO_NO
                   , PO_SEQ
                   , BUYER_ITEM_NO
                   , DESCRIPTION
                   , SPECIFICATION
                   , ITEM_QTY
                   , UNIT_MEASURE
                   , PROCESS_TYPE
                   , SELLER
                   , BUYER_DEPT_CODE
                   , BUYER_PERSON_NAME
                   , BUYER_PERSON_TEL
                   , WMRE_QTY
                   , WMRE_TYPE
                   , WMRE_FILE
                   , B_REQ_DATE
                   , B_REQ_USER_ID
                   , B_REQ_FLAG
                   , FLAG
                   , B_REQ_REMARK   
     			    , WAREHOUSE_CODE

                   )
                   VALUES
                   (  
                     (SELECT   'WM'||TO_CHAR(SYSDATE,'YYMMDD')|| LPAD(COUNT(WMRE_NO)+1,3,0)   AS WMRE_NO
                        FROM   BNTWMRE
                        WHERE SUBSTR(WMRE_NO,3,6) = TO_CHAR(SYSDATE,'YYMMDD'))
                   , #{st_buyer_code}
                   ,#{st_po_no}
                   , #{st_po_seq}
                   ,#{st_buyer_item_no}
                   , #{st_description}
                   , #{st_specification}
                   , #{st_item_qty}
                   , NVL(#{st_unit_measure},' ')
                   , #{st_process_type}
                   ,#{st_seller}
                   , #{st_buyer_dept_code}
                   , #{st_buyer_person_name}
                   , #{st_buyer_person_tel}
                   , #{st_wmre_qty}
                   , #{st_wmre_type}
                   , #{st_wmre_file}
                    ,#{st_b_req_date}
                    ,#{st_user_id}
                    , '02'
                    , '01'
                   ,#{st_b_req_remark}
				   ,#{st_WAREHOUSE_CODE}           
                   )


